"""
Компьютер как руки: с телефона (через облако) — «включи музыку», «громче», «открой VS Code», «пауза».

  • Atlas на компьютере сам держит связь с облаком (каждые ~25 с спрашивает «есть дело?»),
    поэтому ни портов, ни настроек роутера не нужно. Работает и дома, и вне дома.
  • Облако передаёт компьютеру всё, что умеет только он: музыку, программы, громкость, файлы, браузер.
    Компьютер выполняет просьбу своим мозгом и возвращает ответ на телефон.
  • Компьютер выключен — Atlas на телефоне так и скажет, а не «недоступно из облака».
  • Нужно в .env на компьютере: ATLAS_CLOUD_URL=https://atlas-pk9p.onrender.com (адрес облака).

    python apply_hands.py
    python apply_hands.py --rollback
"""
import base64
import hashlib
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
ORIG = {'cloud/atlas_cloud.py': 'eadde25fa13cc71a988d5986cb191ac704044aba3a881ee932e9affa0860d83b', 'main.py': 'f9066d440a2f9d60a5dcffa5450547a67141b3594995b19d771ded0165d95026', 'phone/server.py': '21e889243f1c5577dfa9d1a13ee67b0302ce2df6f596f80192b412cc57024e7c', 'tests/test_cloud_brain.py': '9ed5dfb20645a0394ec8746352c9224661f0a29edf1af95283140b64be1ae3d8', 'tests/test_phone.py': '84b2de0ddfde786bc4a78673c417d4f5872567c1dd11bb88c1f7f856d9657edd', 'core/pc_link.py': None}
NEW = {'cloud/atlas_cloud.py': '', 'main.py': '', 'phone/server.py': '', 'tests/test_cloud_brain.py': '', 'tests/test_phone.py': '', 'core/pc_link.py': ''}
TAG = "backup_hands_"


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel, h in ORIG.items():
        if h is None:
            if os.path.exists(p(rel)):
                os.remove(p(rel))
        else:
            shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith(TAG))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if os.path.exists(p('core/pc_link.py')) and 'def run_agent' in open(p('core/pc_link.py'), encoding="utf-8").read():
    sys.exit("Уже установлено.")

differ = []
for rel, h in ORIG.items():
    if h is None:
        if os.path.exists(p(rel)):
            differ.append(f"{rel} — уже есть такой файл")
        continue
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime(TAG + "%Y%m%d_%H%M%S"))
for rel, h in ORIG.items():
    if h is not None:
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, data in NEW.items():
    os.makedirs(os.path.dirname(p(rel)) or ROOT, exist_ok=True)
    with open(p(rel), "wb") as f:
        f.write(base64.b64decode(data))
print("  ✓ облако передаёт компьютеру музыку, программы, громкость, файлы — через инструмент use_computer")
print("  ✓ компьютер сам держит связь с облаком (без портов и роутера)")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
env_file = p(".env")
has_url = False
if os.path.exists(env_file):
    for ln in open(env_file, encoding="utf-8", errors="replace"):
        if ln.strip().startswith("ATLAS_CLOUD_URL=") and "https://" in ln:
            has_url = True
if not has_url:
    print("\n  ! Добавь в .env строку  ATLAS_CLOUD_URL=https://atlas-pk9p.onrender.com  — иначе компьютер не найдёт облако.")
print("\nГотово. Дальше: git add -A, git commit, git push; потом перезапусти Atlas на компьютере.")
print("В журнале компьютера должно появиться: [руки] связь с облаком есть.")

